import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"中吕·朱履曲归兴","description":"","frontmatter":{"title":"中吕·朱履曲归兴","date":"2026-11-18T00:00:00.000Z","seq":72,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"poem_quote":false,"author":"张可久","source_book":"元曲","prev":{"text":"中吕·普天乐别情","link":"/blogs/元曲·张可久/中吕·普天乐别情.html"},"next":{"text":"双调·庆东原春思","link":"/blogs/元曲·张可久/双调·庆东原春思.html"}},"headers":[],"relativePath":"blogs/元曲·张可久/中吕·朱履曲归兴.md","filePath":"blogs/元曲·张可久/中吕·朱履曲归兴.md"}'),o={name:"blogs/元曲·张可久/中吕·朱履曲归兴.md"};function l(n,a,c,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="中吕·朱履曲归兴" tabindex="-1">中吕·朱履曲归兴 <a class="header-anchor" href="#中吕·朱履曲归兴" aria-label="Permalink to &quot;中吕·朱履曲归兴&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">堂上先生解印，松边雅子迎门，归来不管晋无人。</p><p class="poem-stanza">莺花新伴等，鹅鸭旧比邻，怕称呼陶令尹。</p><p class="poem-stanza">山中书事一梦黄粱高枕，千年《白雪》遗音，野猿嗔客访云林。</p><p class="poem-stanza">瓦沟弹桂子，石磴拂松阴，仙翁留共饮。</p><p class="poem-stanza">秋江晚兴雨骤风狂已过，酒朋诗伴无多，一舸飘然占烟波。</p><p class="poem-stanza">新炊菰米饭，道和〔竹枝〕歌，芦花深处躲。</p><p class="poem-stanza">湖上有感玉雪亭前老树，翠烟桥外平芜，物是人非谩嗟吁。</p><p class="poem-stanza">海榴曾结子，江燕几将雏，名园三换主。</p><p class="poem-stanza">山中晚秋云顶陈抟高枕，山头杜甫长吟，秋客无风到西林。</p><p class="poem-stanza">泉鸣溪漱玉，菊老地铺金，叶红山衣锦。</p><p class="poem-stanza">烂柯洞永日长闲福地，清风自掩岩扉，樵翁随得道童归。</p><p class="poem-stanza">苍松林下月，白石洞中棋，碧云潭上水。</p><p class="poem-stanza">春晚朝雨过红销锦障，晚风狂香散珠囊，杜鹃声里又斜阳。</p><p class="poem-stanza">三月当三十日，一醉抵一千场，绿阴浓芳草长。</p><p class="poem-stanza">仙游二首题姓字《列仙后传》，寄情怀《秋水》全篇，玲珑花月小壶天。</p><p class="poem-stanza">煮黄金还酒债，种白玉结仙缘，袖青蛇□阆苑。</p><p class="poem-stanza">伙火山中丹灶，顺流溪上诗飘，鹤声吹过紫云桥。</p><p class="poem-stanza">苔封山径冷，松倚石床高，花藏仙洞小。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
